def choose_move(observation):
    # Defensive extraction of observation fields
    game_type = observation.get('game_type', '')
    position = observation.get('position', [0, 0])
    x, y = position
    dx, dy = 0, 0

    if game_type == 'resource_collection':
        resources = observation.get('resources', [])
        min_dist = float('inf')
        target = None
        for res in resources:
            if not res:
                continue
            res_x, res_y = res[:2]
            dist = abs(res_x - x) + abs(res_y - y)
            if dist < min_dist:
                min_dist = dist
                target = (res_x, res_y)
        if target:
            dx = 1 if target[0] > x else -1 if target[0] < x else 0
            dy = 1 if target[1] > y else -1 if target[1] < y else 0

    elif game_type == 'pursuit_evasion':
        adversaries = observation.get('adversaries', [])
        min_dist = float('inf')
        target = None
        for adv in adversaries:
            if not adv:
                continue
            adv_x, adv_y = adv[:2]
            dist = abs(adv_x - x) + abs(adv_y - y)
            if dist < min_dist:
                min_dist = dist
                target = (adv_x, adv_y)
        if target:
            dx = 1 if target[0] > x else -1 if target[0] < x else 0
            dy = 1 if target[1] > y else -1 if target[1] < y else 0

    elif game_type == 'territory_control':
        enemy_positions = observation.get('enemy_positions', [])
        min_dist = float('inf')
        threat = None
        for enemy in enemy_positions:
            if not enemy:
                continue
            ex, ey = enemy[:2]
            dist = abs(ex - x) + abs(ey - y)
            if dist < min_dist:
                min_dist = dist
                threat = (ex, ey)
        if threat:
            dx = -1 if threat[0] > x else 1 if threat[0] < x else 0
            dy = -1 if threat[1] > y else 1 if threat[1] < y else 0

    # Bound dx, dy to -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
